import heapq

def solve(n, c, a):
    def partition_sum(start, end):
        length = end - start
        k = length // c
        heap = []
        total_sum = 0
        for i in range(start, end):
            if len(heap) < k:
                heapq.heappush(heap, a[i])
                total_sum += a[i]
            elif a[i] > heap[0]:
                total_sum -= heapq.heappop(heap)
                heapq.heappush(heap, a[i])
                total_sum += a[i]
        return total_sum

