from typing import List

def min_partition_sum(n: int, c: int, a: List[int]) -> int:
    def calculate_value(subarray: List[int]) -> int:
        k = len(subarray)
        threshold = k // c
        if threshold == 0:
            return sum(subarray)
        heap = []
        for i, num in enumerate(subarray):
            if i < threshold:
                heapq.heappush(heap, -num)
            elif -num > heap[0]:
                heapq.heapreplace(heap, -num)
        return sum(subarray) + sum(-x for x in heap)

