import sys
import heapq

def min_partition_sum(n, c, a):
    if c == 1:
        return sum(a)

    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + a[i - 1]

    def get_sum(l, r):
        return prefix_sum[r] - prefix_sum[l]

    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        min_heap = []
        for j in range(i, 0, -1):
            k = (i - j + 1) // c
            if k > 0:
                while min_heap and len(min_heap) > k:
                    heapq.heappop(min_heap)
                if len(min_heap) < k:
                    heapq.heappush(min_heap, a[j - 1])
                if len(min_heap) == k:
                    current_sum = get_sum(j - 1, i) - sum(min_heap)
                    dp[i] = min(dp[i], dp[j - 1] + current_sum)

    return dp[n]

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    c = int(data[1])
    a = list(map(int, data[2:2 + n]))
    result = min_partition_sum(n, c, a)
    print(result)

if __name__ == "__main__":
    main()
